'use client'

import { forwardRef, useId, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import {
  FAQ_ITEMS,
  FAQ_SUPPORT_TEAM,
  FaqHeader,
  FaqSection,
  FaqSupport,
  type FaqItem,
  type FaqPerson,
} from '@/components/blocks/faq/faq'
import { FaqList } from '@/components/blocks/faq/faq-list'

export interface FaqAccordionProps extends Omit<ComponentPropsWithoutRef<'section'>, 'title'> {
  title?: ReactNode
  description?: ReactNode
  items?: FaqItem[]
  supportPeople?: FaqPerson[]
  supportText?: ReactNode
  supportLabel?: string
  supportHref?: string
}

export const FaqAccordion = forwardRef<HTMLElement, FaqAccordionProps>(
  (
    {
      title = 'Frequently asked questions',
      description = 'Installing, theming and licensing, in short answers.',
      items = FAQ_ITEMS,
      supportPeople = FAQ_SUPPORT_TEAM,
      supportText = 'Cannot find what you need?',
      supportLabel = 'Write to the team',
      supportHref = '#',
      ...props
    },
    ref,
  ) => {
    const headingId = useId()

    return (
      <FaqSection ref={ref} labelledBy={headingId} {...props}>
        <div className="grid gap-12 lg:grid-cols-[1fr_1.6fr] lg:gap-16">
          <div className="flex flex-col gap-8">
            <FaqHeader id={headingId} title={title} description={description} />
            <FaqSupport
              people={supportPeople}
              text={supportText}
              linkLabel={supportLabel}
              href={supportHref}
            />
          </div>
          <FaqList items={items} />
        </div>
      </FaqSection>
    )
  },
)
FaqAccordion.displayName = 'FaqAccordion'

'use client'

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion'
import type { FaqItem } from '@/components/blocks/faq/faq'
import { cn } from '@/lib/utils'

export function FaqList({
  items,
  headingLevel = 3,
  className,
}: {
  items: FaqItem[]
  headingLevel?: 3 | 4
  className?: string
}) {
  return (
    <Accordion
      type="single"
      collapsible
      className={cn('gap-0 border-t border-(--color-border)', className)}
    >
      {items.map((item) => (
        <AccordionItem
          key={item.value}
          value={item.value}
          className="rounded-none border-0 border-b border-(--color-border) bg-transparent"
        >
          <AccordionTrigger
            headingLevel={headingLevel}
            className="gap-6 px-0 py-5 text-base hover:bg-transparent focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg)"
          >
            {item.question}
          </AccordionTrigger>
          <AccordionContent className="max-w-xl px-0 pb-6 text-sm text-pretty text-(--color-muted) md:text-base">
            {item.answer}
          </AccordionContent>
        </AccordionItem>
      ))}
    </Accordion>
  )
}

'use client'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import Image from 'next/image'
import { cn } from '@/lib/utils'

export type FaqItem = { value: string; question: string; answer: ReactNode }
export type FaqGroup = { title: string; items: FaqItem[] }
export type FaqPerson = { name: string; src?: string }

export const FAQ_ITEMS: FaqItem[] = [
  {
    value: 'install',
    question: 'How do I install a component?',
    answer:
      'Run the add command shown on its page. The source is copied into your project, so every line is yours to read and change.',
  },
  {
    value: 'tailwind',
    question: 'Do I need Tailwind CSS?',
    answer:
      'Yes. Components are styled with Tailwind v4 utilities and read every color from CSS variables, so they follow your own tokens.',
  },
  {
    value: 'dark-mode',
    question: 'Does it support dark mode?',
    answer:
      'Every component reads semantic tokens that switch under a .dark class on a parent. No component needs its own dark mode code.',
  },
  {
    value: 'accessibility',
    question: 'Are the components accessible?',
    answer:
      'They use semantic HTML, full keyboard support and visible focus rings, and they respect reduced motion. Each page lists its keyboard interactions.',
  },
  {
    value: 'license',
    question: 'Can I use it in a commercial product?',
    answer:
      'Yes. The code is MIT with the Commons Clause: ship your own products with it, just do not resell the components themselves as a kit.',
  },
  {
    value: 'updates',
    question: 'How do updates work?',
    answer:
      'The code lives in your project, so nothing changes on its own. Run the add command again to pull a newer version and review the diff.',
  },
]

export const FAQ_GROUPS: FaqGroup[] = [
  { title: 'Getting started', items: FAQ_ITEMS.slice(0, 2) },
  { title: 'Design and access', items: FAQ_ITEMS.slice(2, 4) },
  { title: 'License and updates', items: FAQ_ITEMS.slice(4, 6) },
]

export const FAQ_SUPPORT_TEAM: FaqPerson[] = [
  { name: 'Maya Okafor' },
  { name: 'Daniel Brandt' },
  { name: 'Priya Raman' },
]

export const FaqSection = forwardRef<
  HTMLElement,
  ComponentPropsWithoutRef<'section'> & { labelledBy: string }
>(({ labelledBy, className, children, ...props }, ref) => (
  <section
    ref={ref}
    aria-labelledby={labelledBy}
    className={cn('w-full bg-(--color-bg) px-6 py-16 sm:px-8 md:py-24', className)}
    {...props}
  >
    <div className="mx-auto w-full max-w-5xl">{children}</div>
  </section>
))
FaqSection.displayName = 'FaqSection'

export function FaqHeader({
  id,
  title,
  description,
}: {
  id: string
  title: ReactNode
  description?: ReactNode
}) {
  return (
    <div className="flex max-w-md flex-col gap-3">
      <h2
        id={id}
        className="text-balance text-2xl font-normal tracking-tight text-(--color-fg) md:text-3xl"
      >
        {title}
      </h2>
      {description && (
        <p className="text-pretty text-sm text-(--color-muted) md:text-base">{description}</p>
      )}
    </div>
  )
}

function initials(name: string) {
  return name
    .split(' ')
    .map((part) => part[0])
    .join('')
    .slice(0, 2)
}

export function FaqAvatar({ person }: { person: FaqPerson }) {
  return (
    <span className="squircle relative flex size-8 shrink-0 items-center justify-center overflow-hidden bg-(--color-surface-2) text-[11px] text-(--color-muted) ring-2 ring-(--color-bg)">
      {person.src ? (
        <Image src={person.src} alt={person.name} fill sizes="32px" className="object-cover" />
      ) : (
        <span aria-hidden="true">{initials(person.name)}</span>
      )}
    </span>
  )
}

export function FaqTextLink({ href, children }: { href: string; children: ReactNode }) {
  return (
    <a
      href={href}
      className="rounded-md text-(--color-fg) underline decoration-(--color-fg)/30 underline-offset-4 transition-[text-decoration-color] duration-(--motion-dur-fast) ease hover:decoration-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none"
    >
      {children}
    </a>
  )
}

export function FaqSupport({
  people,
  text,
  linkLabel,
  href,
}: {
  people: FaqPerson[]
  text: ReactNode
  linkLabel: string
  href: string
}) {
  return (
    <div className="flex flex-col gap-3">
      {people.length > 0 && (
        <div className="flex -space-x-1.5 rtl:space-x-reverse">
          {people.map((person) => (
            <FaqAvatar key={person.name} person={person} />
          ))}
        </div>
      )}
      <p className="max-w-xs text-pretty text-sm text-(--color-muted)">
        {text} {linkLabel && <FaqTextLink href={href}>{linkLabel}</FaqTextLink>}
      </p>
    </div>
  )
}

'use client'

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useId,
  useMemo,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from 'react'
import { useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'

interface AccordionContextValue {
  type: 'single' | 'multiple'
  collapsible: boolean
  expandedValues: string[]
  toggle: (value: string) => void
  reducedMotion: boolean
}

const AccordionContext = createContext<AccordionContextValue | null>(null)

function useAccordionCtx(componentName: string) {
  const ctx = useContext(AccordionContext)
  if (!ctx) throw new Error(`${componentName} must be used within <Accordion>`)
  return ctx
}

interface AccordionItemContextValue {
  value: string
  isExpanded: boolean
  disabled: boolean
  triggerId: string
  contentId: string
}

const AccordionItemContext = createContext<AccordionItemContextValue | null>(null)

function useAccordionItemCtx(componentName: string) {
  const ctx = useContext(AccordionItemContext)
  if (!ctx) throw new Error(`${componentName} must be used within <AccordionItem>`)
  return ctx
}

export interface AccordionProps extends Omit<HTMLAttributes<HTMLDivElement>, 'defaultValue'> {
  type: 'single' | 'multiple'
  collapsible?: boolean
  value?: string | string[]
  defaultValue?: string | string[]
  onValueChange?: (value: string | string[]) => void
  className?: string
  children?: ReactNode
}

export const Accordion = forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      type,
      collapsible = false,
      value: valueProp,
      defaultValue,
      onValueChange,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const isControlled = valueProp !== undefined
    const reducedMotion = useReducedMotion() ?? false

    const normalizeValue = useCallback((v: string | string[] | undefined): string[] => {
      if (v === undefined) return []
      if (Array.isArray(v)) return v
      return v ? [v] : []
    }, [])

    const [internal, setInternal] = useState<string[]>(() => normalizeValue(defaultValue))
    const expandedValues = isControlled ? normalizeValue(valueProp) : internal

    const toggle = useCallback(
      (itemValue: string) => {
        const isExpanded = expandedValues.includes(itemValue)

        let next: string[]

        if (type === 'single') {
          if (isExpanded) {
            next = collapsible ? [] : expandedValues
          } else {
            next = [itemValue]
          }
        } else {
          if (isExpanded) {
            next = expandedValues.filter((v) => v !== itemValue)
          } else {
            next = [...expandedValues, itemValue]
          }
        }

        if (!isControlled) setInternal(next)

        if (onValueChange) {
          onValueChange(type === 'single' ? (next[0] ?? '') : next)
        }
      },
      [type, collapsible, expandedValues, isControlled, onValueChange],
    )

    const ctxValue = useMemo<AccordionContextValue>(
      () => ({ type, collapsible, expandedValues, toggle, reducedMotion }),
      [type, collapsible, expandedValues, toggle, reducedMotion],
    )

    return (
      <AccordionContext.Provider value={ctxValue}>
        <div ref={ref} className={cn('flex flex-col gap-2', className)} {...props}>
          {children}
        </div>
      </AccordionContext.Provider>
    )
  },
)

Accordion.displayName = 'Accordion'

export interface AccordionItemProps extends Omit<HTMLAttributes<HTMLDivElement>, 'value'> {
  value: string
  disabled?: boolean
  className?: string
  children?: ReactNode
}

export const AccordionItem = forwardRef<HTMLDivElement, AccordionItemProps>(
  ({ value, disabled = false, className, children, ...props }, ref) => {
    const { expandedValues } = useAccordionCtx('AccordionItem')
    const isExpanded = expandedValues.includes(value)
    const uid = useId()
    const triggerId = `accordion-trigger-${uid}`
    const contentId = `accordion-content-${uid}`

    const itemCtx = useMemo<AccordionItemContextValue>(
      () => ({ value, isExpanded, disabled, triggerId, contentId }),
      [value, isExpanded, disabled, triggerId, contentId],
    )

    return (
      <AccordionItemContext.Provider value={itemCtx}>
        <div
          ref={ref}
          data-state={isExpanded ? 'open' : 'closed'}
          data-disabled={disabled || undefined}
          className={cn(
            'rounded-md border border-(--color-border) bg-(--color-card) overflow-hidden',
            disabled && 'opacity-50 pointer-events-none',
            className,
          )}
          {...props}
        >
          {children}
        </div>
      </AccordionItemContext.Provider>
    )
  },
)

AccordionItem.displayName = 'AccordionItem'

export interface AccordionTriggerProps extends Omit<HTMLAttributes<HTMLButtonElement>, 'children'> {
  className?: string
  children?: ReactNode
  headingLevel?: 2 | 3 | 4 | 5 | 6
}

export const AccordionTrigger = forwardRef<HTMLButtonElement, AccordionTriggerProps>(
  ({ className, children, headingLevel = 3, ...props }, ref) => {
    const { toggle } = useAccordionCtx('AccordionTrigger')
    const { value, isExpanded, disabled, triggerId, contentId } =
      useAccordionItemCtx('AccordionTrigger')

    const Heading = `h${headingLevel}` as const

    return (
      <Heading className="m-0 flex">
        <button
          ref={ref}
          type="button"
          id={triggerId}
          aria-expanded={isExpanded}
          aria-controls={contentId}
          disabled={disabled}
          onClick={() => toggle(value)}
          className={cn(
            'flex flex-1 items-center justify-between gap-2 px-4 py-3 text-start font-normal text-(--color-fg) outline-none',
            'transition-colors duration-(--motion-dur-fast) ease-(--motion-ease-in-out)',
            'hover:bg-(--color-muted)/50',
            'focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-inset',
            'motion-reduce:transition-none',
            className,
          )}
          {...props}
        >
          <span className="flex-1">{children}</span>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
            className={cn(
              'shrink-0 text-(--color-fg)/60',
              'transition-transform duration-(--motion-dur-base) ease-(--motion-ease-in-out)',
              'motion-reduce:transition-none motion-reduce:transform-none',
              isExpanded && 'rotate-180',
            )}
          >
            <polyline points="6 9 12 15 18 9" />
          </svg>
        </button>
      </Heading>
    )
  },
)

AccordionTrigger.displayName = 'AccordionTrigger'

export interface AccordionContentProps extends HTMLAttributes<HTMLDivElement> {
  className?: string
  children?: ReactNode
}

export const AccordionContent = forwardRef<HTMLDivElement, AccordionContentProps>(
  ({ className, children, ...props }, ref) => {
    const { reducedMotion } = useAccordionCtx('AccordionContent')
    const { isExpanded, triggerId, contentId } = useAccordionItemCtx('AccordionContent')

    return (
      <div
        ref={ref}
        id={contentId}
        role="region"
        aria-labelledby={triggerId}
        inert={!isExpanded}
        hidden={!isExpanded && reducedMotion}
        className={cn(
          'grid',
          'transition-[grid-template-rows] duration-(--motion-dur-base) ease-(--motion-ease-in-out)',
          'motion-reduce:transition-none',
          isExpanded ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]',
        )}
      >
        <div
          className={cn(
            'overflow-hidden',
            'transition-[opacity,transform] duration-(--motion-dur-base) ease-(--motion-ease-in-out)',
            'motion-reduce:transition-none motion-reduce:transform-none',
            isExpanded ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-1',
          )}
        >
          <div className={cn('px-4 pb-3 pt-0 text-sm text-(--color-fg)/80', className)} {...props}>
            {children}
          </div>
        </div>
      </div>
    )
  },
)

AccordionContent.displayName = 'AccordionContent'

export function AccordionPreview() {
  return (
    <div className="flex w-full max-w-md items-center justify-center p-6">
      <Accordion type="single" collapsible defaultValue="item-1" className="w-full">
        <AccordionItem value="item-1">
          <AccordionTrigger>Is it accessible?</AccordionTrigger>
          <AccordionContent>
            Yes. It adheres to the WAI-ARIA design pattern with proper aria-expanded, aria-controls,
            and role=&quot;region&quot; attributes.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="item-2">
          <AccordionTrigger>Is it animated?</AccordionTrigger>
          <AccordionContent>
            Yes. It uses a grid-rows transition with a subtle y-settle for a polished unfold effect.
            Respects prefers-reduced-motion.
          </AccordionContent>
        </AccordionItem>
        <AccordionItem value="item-3">
          <AccordionTrigger>Can I use it controlled?</AccordionTrigger>
          <AccordionContent>
            Yes. Pass value and onValueChange for full controlled state, or use defaultValue for
            uncontrolled.
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    </div>
  )
}
